import Ionicons from '@expo/vector-icons/Ionicons';
import type React from 'react';
import { Lang } from '../habits/types';
import { remote } from '../lib/remoteConfig';
import { reportError } from '../lib/telemetry';

/**
 * Sounds, music, guided audio and calm videos for the Focus tab.
 *
 * Built-in sounds ship with the app (generated by scripts/make_sounds.py, so they are original and
 * licence-free). Everything else comes from the Remote Config parameter `media_catalog` (a JSON
 * array, see RemoteItem), so content can be added without an app update. Only add files you have
 * the rights to (royalty-free with app use allowed, or your own); put credits in `by`.
 */

export type MediaKind = 'sound' | 'music' | 'guided' | 'video';
type IconName = React.ComponentProps<typeof Ionicons>['name'];

export interface MediaItem {
  id: string;
  kind: MediaKind;
  title: Partial<Record<Lang, string>> & { en: string };
  by?: string; // artist / narrator credit
  minutes?: number; // length shown for guided audio and videos
  source: number | string; // bundled asset or https URL
  loop: boolean;
  icon: IconName;
}

const BUILT_IN: MediaItem[] = [
  {
    id: 'lofi-beat',
    kind: 'music',
    title: { en: 'Lofi beat', hi: 'लो-फ़ाई बीट' },
    source: require('../../assets/sounds/lofi-beat.wav'),
    loop: true,
    icon: 'musical-notes-outline',
  },
  {
    id: 'rain',
    kind: 'sound',
    title: { en: 'Rain', hi: 'बारिश' },
    source: require('../../assets/sounds/rain.wav'),
    loop: true,
    icon: 'rainy-outline',
  },
  {
    id: 'brown-noise',
    kind: 'sound',
    title: { en: 'Brown noise', hi: 'ब्राउन नॉइज़' },
    source: require('../../assets/sounds/brown-noise.wav'),
    loop: true,
    icon: 'pulse-outline',
  },
];

/** Shape of one entry in the `media_catalog` Remote Config JSON array. */
interface RemoteItem {
  id: string;
  kind: MediaKind;
  title: { en: string; hi?: string };
  url: string; // https only, e.g. a Firebase Storage download URL
  by?: string;
  minutes?: number;
}

const ICONS: Record<MediaKind, IconName> = {
  sound: 'leaf-outline',
  music: 'musical-notes-outline',
  guided: 'headset-outline',
  video: 'play-circle-outline',
};

const isRemoteItem = (x: unknown): x is RemoteItem => {
  const o = x as RemoteItem;
  return (
    typeof o === 'object' && o !== null &&
    typeof o.id === 'string' && o.id.length > 0 &&
    ['sound', 'music', 'guided', 'video'].includes(o.kind) &&
    typeof o.title?.en === 'string' &&
    typeof o.url === 'string' && o.url.startsWith('https://') &&
    (o.minutes === undefined || typeof o.minutes === 'number')
  );
};

let cache: { raw: string; items: MediaItem[] } | null = null;

/** Built-in sounds plus valid remote items (bad entries are skipped, never crash the screen). */
export function mediaCatalog(): MediaItem[] {
  const raw = remote.mediaCatalog();
  if (cache?.raw === raw) return cache.items;
  let extra: MediaItem[] = [];
  if (raw) {
    try {
      const list: unknown = JSON.parse(raw);
      extra = (Array.isArray(list) ? list : []).filter(isRemoteItem)
        .filter((r) => !BUILT_IN.some((b) => b.id === r.id))
        .map((r) => ({
          id: r.id,
          kind: r.kind,
          title: r.title,
          by: r.by,
          minutes: r.minutes,
          source: r.url,
          loop: r.kind === 'sound' || r.kind === 'music',
          icon: ICONS[r.kind],
        }));
    } catch (e) {
      reportError(e, 'media_catalog');
    }
  }
  cache = { raw, items: [...BUILT_IN, ...extra] };
  return cache.items;
}

export const mediaTitle = (item: MediaItem, lang: Lang) => item.title[lang] ?? item.title.en;
export const findMedia = (id: string) => mediaCatalog().find((m) => m.id === id);
